private void ExportToHTML()
{
    if (dtbData == null || dtbData.Rows.Count <= 0 || dtbClassSubject == null)
        return;

    GetSetting();

    string strTemplate = "MauHTML/BangDiem_TongKet_A4.htm";
    string strFileContent = Libs.Files.ReadFile(strTemplate);

    string strHeader1 = strReport_Header_Text;
    string strHeader2 = strReport_Header2_Text;
    if (strHeader1 == null || strHeader1 == "")
        strHeader1 = strReport_Header;
    if (strHeader2 == null)
        strHeader2 = "";

    string strTitle = "";
    string strSubtitle = "";
    if (uYearSemester.SemesterEditValue == null)
    {
        strTitle = "BẢNG TỔNG KẾT KẾT QUẢ HỌC TẬP NIÊN HỌC " + uYearSemester.YearEditValueText;
        strSubtitle = "(Lấy kết quả điểm kiểm tra, điểm tổng kết môdun/môn học lần cao nhất)";
    }
    else if (chkViewOnlyExam1.Checked)
    {
        strTitle = String.Format("BẢNG TỔNG KẾT KẾT QUẢ HỌC TẬP HỌC KÌ {0} LẦN 1 NĂM HỌC {1}",
            uYearSemester.SemesterEditValue.ToString(), uYearSemester.YearEditValueText);
        strSubtitle = "(Lấy kết quả điểm kiểm tra, điểm tổng kết môdun/môn học lần 1)";
    }
    else
    {
        strTitle = String.Format("BẢNG TỔNG KẾT KẾT QUẢ HỌC TẬP HỌC KÌ {0} LẦN CAO NHẤT NĂM HỌC {1}",
            uYearSemester.SemesterEditValue.ToString(), uYearSemester.YearEditValueText);
        strSubtitle = "(Lấy kết quả điểm kiểm tra, điểm tổng kết môdun/môn học lần cao nhất)";
    }

    DateTime dtmNow = SystemService.SYS_SettingService.CurrentDateTime;
    string strPlace = strReport_Place
        + ", ngày " + dtmNow.Day.ToString()
        + " tháng " + dtmNow.Month.ToString()
        + " năm " + dtmNow.Year.ToString();

    strFileContent = strFileContent.Replace("{HEADER_TEXT}", strHeader1);
    strFileContent = strFileContent.Replace("{HEADER2_TEXT}", strHeader2);
    strFileContent = strFileContent.Replace("{TITLE}", strTitle);
    strFileContent = strFileContent.Replace("{SUBTITLE}", strSubtitle);
    strFileContent = strFileContent.Replace("{COURSE}", uClass.CourseName);
    strFileContent = strFileContent.Replace("{TRAINING_LEVEL}", uClass.TrainingLevelName);
    strFileContent = strFileContent.Replace("{TRAINING_TYPE}", uClass.TrainingTypeName);
    strFileContent = strFileContent.Replace("{BRANCH}", uClass.BranchName);
    strFileContent = strFileContent.Replace("{SPECIAL_BRANCH}", uClass.SpecialBranchName);
    strFileContent = strFileContent.Replace("{CLASS}", uClass.ClassName);
    strFileContent = strFileContent.Replace("{TOTAL}", dtbData.Rows.Count.ToString());
    strFileContent = strFileContent.Replace("{PLACE}", strPlace);
    strFileContent = strFileContent.Replace("{STATISTICS}", StatisticToHTML());
    strFileContent = strFileContent.Replace("{DETAIL}", DetailToHTML());

    string strFileNameAs = uClass.ClassIDEditValue + "_BangDiem_TongKet.htm";
    Libs.Files.WriteFile(strFileNameAs, strFileContent);
    System.Diagnostics.Process.Start(strFileNameAs);
}

private string DetailToHTML()
{
    bool bolLan1 = chkViewOnlyExam1.Checked;
    string strMarkField = bolLan1 ? "Summary1_" : "FinalSummary_";
    string strOtherField = bolLan1 ? "OtherSummary1_" : "OtherFinalSummary_";

    string strHeader1 = "<tr>";
    string strHeader2 = "<tr>";
    string strHeader3 = "<tr>";
    string strRows = "";

    strHeader1 += "<th rowspan='3' class='col-tt'>TT</th>"
                + "<th rowspan='3' class='col-code'>Mã số</th>"
                + "<th rowspan='3' class='col-name first'>Họ và tên</th>"
                + "<th rowspan='3' class='col-name last'>&nbsp;</th>";

    foreach (DataRow drwSubject in dtbClassSubject.Rows)
    {
        string strSubjectName = drwSubject["SubjectShortName"].ToString();
        string strUnitText = drwSubject["UnitText"].ToString();
        if (strUnitText == "")
            strUnitText = "&nbsp;";

        strHeader1 += "<th colspan='2' class='subject'><span>" + strSubjectName + "</span></th>";
        strHeader2 += "<th class='subcol'>TBC<br />(Hệ 10)</th><th class='subcol'>TBC<br />(Hệ 4)</th>";
        strHeader3 += "<th colspan='2'>" + strUnitText + "</th>";
    }

    strHeader1 += "<th rowspan='3' class='subject'><span>Điểm TBC Hệ 10</span></th>"
                + "<th rowspan='3' class='subject'><span>Điểm TBC Hệ 4</span></th>"
                + "<th rowspan='3' class='subject'><span>Điểm rèn luyện</span></th>"
                + "<th rowspan='3'>Số<br />môn<br />&lt;4</th>"
                + "<th rowspan='3'>Xếp loại</th>";
    strHeader1 += "</tr>";
    strHeader2 += "</tr>";
    strHeader3 += "</tr>";

    int intTT = 1;
    foreach (DataRow drwStudent in dtbData.Rows)
    {
        string strRow = "<tr>"
            + "<td>" + intTT.ToString() + "</td>"
            + "<td class='code'>" + drwStudent["StudentCode"].ToString() + "</td>"
            + "<td class='name first'>" + drwStudent["StudentFirstName"].ToString() + "</td>"
            + "<td class='name last'>" + drwStudent["StudentLastName"].ToString() + "</td>";

        int j = 1;
        foreach (DataRow drwSubject in dtbClassSubject.Rows)
        {
            string strFinal = FormatMark(drwStudent[strMarkField + j.ToString()].ToString());
            string strOther = FormatMark(drwStudent[strOtherField + j.ToString()].ToString());
            strRow += "<td" + MarkRedStyle(strFinal) + ">" + strFinal + "</td>"
                    + "<td>" + strOther + "</td>";
            j++;
        }

