        string strTbc4 = drwStudent["OtherSummaryLearningMark"].ToString();
        string strEthic = "";
        if (dtbData.Columns.Contains("EthicMark") && drwStudent["EthicMark"] != DBNull.Value)
            strEthic = drwStudent["EthicMark"].ToString();
        string strDebt = drwStudent["SomeDebt"].ToString();
        string strLevel = drwStudent["LearningLevel"].ToString();

        strRow += "<td class='bold'>" + strTbc10 + "</td>"
                + "<td>" + strTbc4 + "</td>"
                + "<td>" + strEthic + "</td>"
                + "<td>" + strDebt + "</td>"
                + "<td>" + strLevel + "</td>"
                + "</tr>";
        strRows += strRow;
        intTT++;
