    strColGroup += "<col class='c-tbc' /><col class='c-tbc' /><col class='c-ethic' /><col class='c-debt' /><col class='c-xl' />"
        + "</colgroup>";

    return "<table class='main'>"
        + strColGroup
        + "<thead>"
        + strHeader1
        + strHeader2
        + strHeader3
        + "</thead><tbody>"
        + strRows
        + "</tbody></table>";
}

private string MarkRedStyle(string strFinal)
{
    if (strFinal == "" || strFinal == "&nbsp;" || strFinal == "M" || strFinal == "Đ" || strFinal == "CĐ")
        return "";
    try
    {
        if (Convert.ToDouble(strFinal.Replace(",", ".")) < 5)
            return " class='markRed'";
    }
    catch
    {
    }
    return "";
}

private string FormatMark(string strValue)
{
    if (strValue == null || strValue == "")
        return "&nbsp;";
    if (strValue == "-1" || strValue == "-1,0" || strValue == "-10")
        return "M";
    if (strValue == "110")
        return "Đ";
    if (strValue == "100")
        return "CĐ";
    if (strValue == "10,00" || strValue == "10,0")
        return "10";
    return strValue;
}

private string StatisticToHTML()
{
    double iTB = 0;
    double iTBKha = 0;
    double iKha = 0;
    double iTot = 0;
    double iXuatSac = 0;
    double iSV = 0;
    double iYeu = 0;

    if ((intRegulationIDCurrent == 43 || intRegulationIDCurrent == 99 || intRegulationIDCurrent == 44) && !chkXemTheoNienChe.Checked)
    {
        for (int j = 0; j < dtbData.Rows.Count; j++)
        {
            iSV += 1;
            if (Convert.ToDouble(dtbData.Rows[j]["OtherSummaryLearningMark"]) > 3.5)
                iXuatSac += 1;
            else if (Convert.ToDouble(dtbData.Rows[j]["OtherSummaryLearningMark"]) >= 3.2)
                iTot += 1;
            else if (Convert.ToDouble(dtbData.Rows[j]["OtherSummaryLearningMark"]) >= 2.5)
                iKha += 1;
            else if (Convert.ToDouble(dtbData.Rows[j]["OtherSummaryLearningMark"]) >= 2.0)
                iTB += 1;
            else
                iYeu += 1;
        }
    }
    else
    {
        for (int j = 0; j < dtbData.Rows.Count; j++)
        {
            iSV += 1;
            if (Convert.ToString(dtbData.Rows[j]["LearningLevel"]) == "Yếu" || Convert.ToString(dtbData.Rows[j]["LearningLevel"]) == "Kém")
                iYeu += 1;
            else if (Convert.ToString(dtbData.Rows[j]["LearningLevel"]) == "Trung bình")
                iTB += 1;
            else if (Convert.ToString(dtbData.Rows[j]["LearningLevel"]) == "TB khá")
                iTBKha += 1;
            else if (Convert.ToString(dtbData.Rows[j]["LearningLevel"]) == "Khá")
                iKha += 1;
            else if (Convert.ToString(dtbData.Rows[j]["LearningLevel"]) == "Giỏi")
                iTot += 1;
            else if (Convert.ToString(dtbData.Rows[j]["LearningLevel"]) == "Xuất sắc")
                iXuatSac += 1;
        }
    }

    if (iSV <= 0)
        iSV = 1;

    string strRow = "<table class='statistics'>"
        + "<tr>"
        + "<td class='caption'>Xếp loại</td><td class='caption'>SL</td><td class='caption'>Tỉ lệ</td>"
        + "<td class='caption'>Xếp loại</td><td class='caption'>SL</td><td class='caption'>Tỉ lệ</td>"
        + "</tr>"
        + "<tr>"
        + "<td>Xuất sắc</td><td>" + iXuatSac.ToString() + "</td><td>" + Math.Round(iXuatSac * 100.0 / iSV, 2).ToString() + "%</td>"
        + "<td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td>"
        + "</tr>"
        + "<tr>"
        + "<td>Giỏi</td><td>" + iTot.ToString() + "</td><td>" + Math.Round(iTot * 100.0 / iSV, 2).ToString() + "%</td>"
        + "<td>TB</td><td>" + iTB.ToString() + "</td><td>" + Math.Round(iTB * 100.0 / iSV, 2).ToString() + "%</td>"
        + "</tr>"
        + "<tr>"
        + "<td>Khá</td><td>" + iKha.ToString() + "</td><td>" + Math.Round(iKha * 100.0 / iSV, 2).ToString() + "%</td>"
        + "<td>Yếu</td><td>" + iYeu.ToString() + "</td><td>" + Math.Round(iYeu * 100.0 / iSV, 2).ToString() + "%</td>"
        + "</tr>";

    if (iTBKha > 0)
    {
        strRow += "<tr>"
            + "<td>TB khá</td><td>" + iTBKha.ToString() + "</td><td>" + Math.Round(iTBKha * 100.0 / iSV, 2).ToString() + "%</td>"
            + "<td>&nbsp;</td><td>&nbsp;</td><td>&nbsp;</td>"
            + "</tr>";
    }

    strRow += "</table>";
    return strRow;
}

