private void SetBangDiemTongKetReportParameters(SystemManager.Report.frmReportView frm, DataTable dtbPrint)
{
    double iTB = 0;
    double iTBKha = 0;
    double iKha = 0;
    double iTot = 0;
    double iXuatSac = 0;
    double iSV = 0;
    double iYeu = 0;

    if ((intRegulationIDCurrent == 43 || intRegulationIDCurrent == 99 || intRegulationIDCurrent == 44) && !chkXemTheoNienChe.Checked)
    {
        for (int j = 0; j < dtbPrint.Rows.Count; j++)
        {
            iSV += 1;
            if (Convert.ToDouble(dtbPrint.Rows[j]["OtherSummaryLearningMark"]) > 3.5)
                iXuatSac += 1;
            else if (Convert.ToDouble(dtbPrint.Rows[j]["OtherSummaryLearningMark"]) >= 3.2)
                iTot += 1;
            else if (Convert.ToDouble(dtbPrint.Rows[j]["OtherSummaryLearningMark"]) >= 2.5)
                iKha += 1;
            else if (Convert.ToDouble(dtbPrint.Rows[j]["OtherSummaryLearningMark"]) >= 2.0)
                iTB += 1;
            else
                iYeu += 1;
        }
    }
    else
    {
        for (int j = 0; j < dtbPrint.Rows.Count; j++)
        {
            iSV += 1;
            if (Convert.ToString(dtbPrint.Rows[j]["LearningLevel"]) == "Yếu" || Convert.ToString(dtbPrint.Rows[j]["LearningLevel"]) == "Kém")
                iYeu += 1;
            else if (Convert.ToString(dtbPrint.Rows[j]["LearningLevel"]) == "Trung bình")
                iTB += 1;
            else if (Convert.ToString(dtbPrint.Rows[j]["LearningLevel"]) == "TB khá")
                iTBKha += 1;
            else if (Convert.ToString(dtbPrint.Rows[j]["LearningLevel"]) == "Khá")
                iKha += 1;
