private string MarkRedStyleHe4(string strValue)
{
    if (strValue == "" || strValue == "&nbsp;" || strValue == "M")
        return "";
    try
    {
        if (Convert.ToDouble(strValue.Replace(",", ".")) < 1)
            return " class='markRed'";
    }
    catch
    {
    }
    return "";
}

private string MarkRedStyleTk(string strValue)
{
    if (strValue == "" || strValue == "&nbsp;" || strValue == "M" || strValue == "Đ" || strValue == "CĐ")
        return "";
    try
    {
        if (Convert.ToDouble(strValue.Replace(",", ".")) < 5)
            return " class='markRed'";
    }
    catch
    {
    }
    return "";
}

private string FormatMarkHe4(string strValue)
{
    if (strValue == null || strValue == "")
        return "&nbsp;";
    if (strValue == "-1" || strValue == "-1,0" || strValue == "-10")
        return "M";
    return strValue;
}

private string FormatMark(string strValue)
{
    if (strValue == null || strValue == "")
        return "&nbsp;";
    if (strValue == "-1" || strValue == "-1,0" || strValue == "-10")
        return "M";
    if (strValue == "110")
        return "Đ";
    if (strValue == "100")
        return "CĐ";
    if (strValue == "10,00" || strValue == "10,0")
        return "10";
    return strValue;
}

